import requests
for q in ['"3-C-demethyl-4-C-O-methylmithramycin" HIV','varamycin HIV','"3(C)-Demethyl-4(C)-O-methylmithramycin" antiviral','mithramycin HIV replication']:
 u='https://www.ebi.ac.uk/europepmc/webservices/rest/search'
 r=requests.get(u,params={'query':q,'format':'json','pageSize':10},headers={'User-Agent':'Mozilla/5.0'})
 print('\nQUERY',q,'STATUS',r.status_code)
 for x in r.json().get('resultList',{}).get('result',[]): print(x.get('title'),x.get('pmid'),x.get('doi'))

